package com.tcs.agentia.order.resource;

import com.tcs.agentia.order.Order;
import com.tcs.agentia.order.repository.OrderRepository;
import io.quarkus.panache.common.Page;
import jakarta.inject.Inject;
import jakarta.transaction.Transactional;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotNull;
import jakarta.ws.rs.*;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.Response;
import java.net.URI;
import java.util.List;
import java.util.UUID;

@Path("/api/order")
@Produces(MediaType.APPLICATION_JSON)
@Consumes(MediaType.APPLICATION_JSON)
public class OrderResource {

    @Inject
    OrderRepository repository;

    @GET
    public List<Order> list(
        @QueryParam("page") @DefaultValue("0") int page,
        @QueryParam("size") @DefaultValue("20") int size
    ) {
        if (size <= 0) {
            return repository.listAll();
        }
        int safePage = Math.max(page, 0);
        int safeSize = Math.min(size, 100);
        return repository.findAll().page(Page.of(safePage, safeSize)).list();
    }

    @GET
    @Path("/{id}")
    public Response getById(@PathParam("id") Long id) {
        return repository.findByIdOptional(id)
            .map(entity -> Response.ok(entity).build())
            .orElseGet(() -> Response.status(Response.Status.NOT_FOUND).build());
    }

    @POST
    @Transactional
    public Response create(@Valid @NotNull Order entity) {
        entity.setId(null);
        repository.persist(entity);
        return Response.created(URI.create("/api/order/" + entity.getId())).entity(entity).build();
    }

    @PUT
    @Path("/{id}")
    @Transactional
    public Response update(@PathParam("id") Long id, @Valid @NotNull Order updated) {
        Order existing = repository.findById(id);
        if (existing == null) {
            return Response.status(Response.Status.NOT_FOUND).build();
        }
        if (updated.getCustomerEmail() != null) {
            existing.setCustomerEmail(updated.getCustomerEmail());
        }
        if (updated.getTotalAmount() != null) {
            existing.setTotalAmount(updated.getTotalAmount());
        }
        if (updated.getStatus() != null) {
            existing.setStatus(updated.getStatus());
        }
        if (updated.getCreatedAt() != null) {
            existing.setCreatedAt(updated.getCreatedAt());
        }
        return Response.ok(existing).build();
    }

    @DELETE
    @Path("/{id}")
    @Transactional
    public Response delete(@PathParam("id") Long id) {
        boolean deleted = repository.deleteById(id);
        if (!deleted) {
            return Response.status(Response.Status.NOT_FOUND).build();
        }
        return Response.status(Response.Status.NO_CONTENT).build();
    }
}

package com.tcs.agentia.order.resource;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import static io.restassured.RestAssured.given;
import static org.hamcrest.CoreMatchers.*;

@QuarkusTest
public class OrderResourceTest {

    @Test
    public void testListEndpoint() {
        given()
            .when().get("/api/order")
            .then()
            .statusCode(200);
    }

    @Test
    public void testGetNotFoundEndpoint() {
        given()
            .when().get("/api/order/999999")
            .then()
            .statusCode(404);
    }

    @Test
    public void testCreateGetUpdateAndDeleteLifecycle() {
        Object createdId = given()
            .contentType(ContentType.JSON)
            .body("{\"customerEmail\": \"user3@example.com\", \"totalAmount\": 300.0, \"status\": \"sample_status_3\", \"createdAt\": \"2026-10-16T12:00:00Z\"}")
            .when().post("/api/order")
            .then()
            .statusCode(201)
            .body("id", notNullValue())
            .extract().path("id");

        given()
            .when().get("/api/order/" + createdId)
            .then()
            .statusCode(200)
            .body("id", notNullValue());

        given()
            .contentType(ContentType.JSON)
            .body("{\"customerEmail\": \"user4@example.com\", \"totalAmount\": 400.0, \"status\": \"sample_status_4\", \"createdAt\": \"2026-10-17T12:00:00Z\"}")
            .when().put("/api/order/" + createdId)
            .then()
            .statusCode(200)
            .body("customerEmail", equalTo("user4@example.com"));

        given()
            .when().delete("/api/order/" + createdId)
            .then()
            .statusCode(204);

        given()
            .when().get("/api/order/" + createdId)
            .then()
            .statusCode(404);
    }

    @Test
    public void testUpdateNotFoundEndpoint() {
        given()
            .contentType(ContentType.JSON)
            .body("{\"customerEmail\": \"user4@example.com\", \"totalAmount\": 400.0, \"status\": \"sample_status_4\", \"createdAt\": \"2026-10-17T12:00:00Z\"}")
            .when().put("/api/order/999999")
            .then()
            .statusCode(404);
    }

    @Test
    public void testDeleteNotFoundEndpoint() {
        given()
            .when().delete("/api/order/999999")
            .then()
            .statusCode(404);
    }
}

package com.tcs.agentia.order.repository;

import com.tcs.agentia.order.Order;
import io.quarkus.test.junit.QuarkusTest;
import jakarta.inject.Inject;
import jakarta.transaction.Transactional;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.Instant;
import java.util.UUID;

@QuarkusTest
public class OrderRepositoryTest {

    @Inject
    OrderRepository repository;

    @Test
    @Transactional
    public void testPersistAndFind() {
        repository.deleteAll();
        Order entity = new Order();
        entity.setCustomerEmail("Sample");
        entity.setTotalAmount(new BigDecimal("100.00"));
        entity.setStatus("Sample");
        entity.setCreatedAt(Instant.now());

        repository.persist(entity);
        assertNotNull(entity.getId());
        assertTrue(repository.findByIdOptional(entity.getId()).isPresent());
        assertNotNull(repository.findById(entity.getId()));
        repository.deleteById(entity.getId());
    }

    @Test
    @Transactional
    public void testDelete() {
        repository.deleteAll();
        Order entity = new Order();
        entity.setCustomerEmail("Sample_2");
        entity.setTotalAmount(new BigDecimal("200.00"));
        entity.setStatus("Sample_2");
        entity.setCreatedAt(Instant.now());

        repository.persist(entity);
        Long id = entity.getId();
        assertNotNull(id);

        boolean deleted = repository.deleteById(id);
        assertTrue(deleted);
        assertTrue(repository.findByIdOptional(id).isEmpty());
    }
}

